#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("NO_INPUT\n");
        return 0;
    }

    long num1 = strtol(argv[1], NULL, 10);
    long num2 = strtol(argv[2], NULL, 10);

    if (num1 == 0 || num2 == 0) {
        printf("BAD_INPUT\n");
        return 0;
    }

    long result = 0;
    int count = 0;
    while (num1 != 0 && num2 != 0) {
        long quotient = num1 / num2;
        long remainder = num1 % num2;
        printf("%ld", quotient);
        if (remainder != 0) {
            printf(", ");
        }
        num1 = num2;
        num2 = remainder;
        count++;
        if (count > 100000) {
            printf("OUT_OF_RANGE\n");
            return 0;
        }
    }

    printf("\n");
    return 0;
}
